from datetime import date, timedelta
from billing.calendar import add_months, cycle_bounds
checks = 0
for year in (1999, 2000, 2024, 2026, 2028, 2096, 2100):
    for month in range(1, 13):
        for day in (28, 29, 30, 31):
            try:
                anchor = date(year, month, day)
            except ValueError:
                continue
            for interval, step, count in (('month', 1, 36), ('year', 12, 8)):
                renewals = [add_months(anchor, step * k) for k in range(count + 1)]
                for start, end in zip(renewals, renewals[1:]):
                    for on in (start, start + timedelta(days=1), end - timedelta(days=1)):
                        assert cycle_bounds(anchor, on, interval) == (start, end), (anchor, on, interval)
                        checks += 1
print(f'Calendar boundary reference checks passed: {checks}')
